window.renderStudentNotes=function(){
 const subject=window.currentSubject||'termicas';
 const notes=window.studentNotesBySubject?.[subject]||[];
 document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#estudiantes'));
 const container=document.querySelector('#app');
 container.innerHTML=head('LECTURAS DE LA MATERIA','Notas de estudiantes','Primero el texto original del estudiante; debajo, la versión revisada por ChatGPT con aclaraciones y fuentes.')+
 (notes.length?`<div class="student-note-index" aria-label="Ir a una nota">${notes.map((note,i)=>`<button class="secondary" data-student-note-target="student-note-${i}">${esc(note.title)} · ${esc(note.subtitle||'Fundamentos de motores térmicos')}</button>`).join('')}</div>`+notes.map((note,i)=>`<article class="student-note" id="student-note-${i}" tabindex="-1"><header class="student-note-heading"><div><p class="eyebrow">${esc(note.subject)} · ${esc(note.date)}</p><h2>${esc(note.title)}</h2><p>${esc(note.subtitle||'Fundamentos de motores térmicos')}</p></div><a class="button secondary" href="${esc(note.originalUrl)}" target="_blank" rel="noopener">Leer original en Drive ↗</a></header><section aria-labelledby="student-original-${i}"><h3 id="student-original-${i}">Texto original del estudiante</h3><p class="source">Transcripción íntegra. Conserva las expresiones ambiguas del dictado; las aclaraciones están en la revisión que sigue.</p><p class="student-original-text">${esc(note.original)}</p></section><section class="student-revision" aria-labelledby="student-revised-${i}"><p class="eyebrow">REVISIÓN TÉCNICA · CHATGPT</p><h3 id="student-revised-${i}">${esc(note.revisedTitle)}</h3><a href="${esc(note.revisedUrl)}" target="_blank" rel="noopener">Abrir la versión revisada en Drive ↗</a>${note.intro?`<p>${esc(note.intro)}</p>`:''}${note.sections.map(s=>`<h4>${esc(s.title)}</h4><p>${esc(s.text)}</p>`).join('')}<h4>Aclaraciones sobre la transcripción</h4><ul>${note.corrections.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h4>Fuentes de consulta</h4><ul>${note.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></li>`).join('')}</ul></section></article>`).join(''):'<p class="subject-empty">Todavía no hay notas de estudiantes publicadas para esta materia. Las notas de motores están en Motores navales.</p>');
 container.querySelectorAll('[data-student-note-target]').forEach(button=>button.onclick=()=>{const note=document.getElementById(button.dataset.studentNoteTarget);note?.focus({preventScroll:true});note?.scrollIntoView({block:'start'});});
};
